package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
)

func main() {
	asJSON := flag.Bool("json", false, "print the result as JSON")
	flag.Parse()
	if *asJSON {
		_ = json.NewEncoder(os.Stdout).Encode(map[string]int{"files": len(flag.Args())})
		return
	}
	fmt.Printf("%d files\n", len(flag.Args()))
}
